s = "savefromtheavalanche"
t = "av"
r = len(s)
p = len(t)
i = 0
while i <= len(s) - p:
    j, u = 0, 0
    if s[i] == t[j]:
        for j in range(1, p):
            if s[i + j] != t[j]:
                u = 1
                i += 1
                break
        if not u:
            i += p
            r -= p - 1
    else:
        i += 1
print(r)
